INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('breast', 'Lesion Characterization (ACR BI-RADS)', 'High-frequency linear 10–18 MHz + SWE if available', '[{"id": "breast_lesion_0", "label": "Shape: oval / round / irregular", "detail": "Irregular shape = BI-RADS 4-5 feature", "critical": false}, {"id": "breast_lesion_1", "label": "Orientation: parallel (horizontal) vs not parallel (vertical)", "detail": "Not parallel (taller-than-wide) = suspicious", "critical": true}, {"id": "breast_lesion_2", "label": "Margin: circumscribed / not circumscribed (indistinct, angular, microlobulated, spiculated)", "detail": "Spiculated margin = BI-RADS 5", "critical": true}, {"id": "breast_lesion_3", "label": "Echo pattern: anechoic / hyperechoic / complex / hypoechoic / isoechoic / heterogeneous", "detail": "", "critical": false}, {"id": "breast_lesion_4", "label": "Posterior features: no posterior features / enhancement / shadowing / combined", "detail": "", "critical": false}, {"id": "breast_lesion_5", "label": "Calcifications: macrocalcifications / microcalcifications in mass", "detail": "Microcalcifications in mass = BI-RADS 4B-5", "critical": true}, {"id": "breast_lesion_6", "label": "Vascularity: color Doppler — internal vs peripheral", "detail": "", "critical": false}]', 2);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('breast', 'Ultrasound-Guided Biopsy (Core / FNA / VAB)', 'Linear 12–18 MHz | Freehand in-plane technique', '[{"id": "breast_biopsy_0", "label": "Target lesion confirmed — size, location, depth from skin and chest wall", "detail": "Compare with prior imaging. Confirm BI-RADS category warrants biopsy.", "critical": true}, {"id": "breast_biopsy_1", "label": "Needle trajectory planned — parallel to chest wall, avoiding vessels and implants", "detail": "Lateral approach preferred. Confirm throw distance will not reach pleura.", "critical": true}, {"id": "breast_biopsy_2", "label": "Real-time needle visualisation — tip confirmed within lesion before firing", "detail": "Heel-toe transducer angulation improves tip visualisation if obscured by shadowing.", "critical": true}, {"id": "breast_biopsy_3", "label": "Core biopsy: minimum 3 passes (14-gauge) | FNA: 25-gauge | VAB: 7-11 gauge", "detail": "Specimen radiograph for calcifications confirms retrieval.", "critical": false}, {"id": "breast_biopsy_4", "label": "Biopsy clip marker deployed and confirmed post-procedure", "detail": "Post-procedure mammogram confirms clip position. Essential if lesion resolves after biopsy.", "critical": true}, {"id": "breast_biopsy_5", "label": "Post-procedure haematoma assessed — apply pressure, document size", "detail": "", "critical": false}]', 3);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('breast', 'Pre-Surgical Lumpectomy Localisation', 'Linear 12–18 MHz | Freehand in-plane technique', '[{"id": "breast_lump_0", "label": "Target lesion or biopsy clip confirmed — correlate with prior mammogram", "detail": "Clip migration can occur — always correlate with post-biopsy mammogram before localisation.", "critical": true}, {"id": "breast_lump_1", "label": "Lesion depth from skin and distance from chest wall measured", "detail": "", "critical": true}, {"id": "breast_lump_2", "label": "Localisation device trajectory planned (wire / RSL seed / SAVI SCOUT)", "detail": "Wire tip should be within 1 cm of lesion. RSL/SAVI SCOUT placed within lesion.", "critical": true}, {"id": "breast_lump_3", "label": "Device tip position confirmed within lesion in two planes post-placement", "detail": "", "critical": true}, {"id": "breast_lump_4", "label": "Post-procedure mammogram performed to confirm device position", "detail": "Required for wire and RSL localisation before patient leaves department.", "critical": true}]', 4);

INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('thyroid', 'Right Thyroid Lobe', 'High-frequency linear 10–18 MHz; patient supine, neck extended', '[{"id": "thyroid_rt_0", "label": "Longitudinal and transverse views — measure length, width, AP diameter", "detail": "Normal lobe: length 4-6 cm, width 1.5-2 cm, AP 1.5-2 cm", "critical": false}, {"id": "thyroid_rt_1", "label": "Parenchymal echogenicity and vascularity (color Doppler)", "detail": "Diffuse hypervascularity = Graves disease; hypoechoic = thyroiditis", "critical": false}, {"id": "thyroid_rt_2", "label": "Nodule characterization — ACR TI-RADS: composition, echogenicity, shape, margin, echogenic foci", "detail": "TR1=benign, TR2=not suspicious, TR3=mildly suspicious, TR4=moderately suspicious, TR5=highly suspicious", "critical": false}]', 0);
