INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('thyroid', 'Cervical Lymph Nodes', 'High-frequency linear 10–18 MHz', '[{"id": "thyroid_ln_0", "label": "Bilateral cervical chain levels II-VI — size, shape, echogenicity, vascularity", "detail": "Suspicious: round shape, loss of fatty hilum, cystic change, microcalcifications", "critical": true}, {"id": "thyroid_ln_1", "label": "Short-axis diameter of largest node", "detail": "Short axis greater than 1 cm = abnormal; less than 1 cm with suspicious features = biopsy consideration", "critical": false}]', 3);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('thyroid', 'Ultrasound-Guided FNA / Core Biopsy', 'Linear 12–18 MHz | Freehand in-plane technique', '[{"id": "thyroid_bx_0", "label": "Target nodule confirmed — ACR TI-RADS category and size meet biopsy threshold", "detail": "ACR TI-RADS biopsy thresholds: TR5 >=1 cm, TR4 >=1.5 cm, TR3 >=2.5 cm, TR2 >=3 cm. TR1 = no biopsy.", "critical": true}, {"id": "thyroid_bx_1", "label": "Needle trajectory planned — lateral to medial, parallel to trachea, avoiding carotid and IJV", "detail": "Transverse approach (needle in-plane with transducer) preferred for thyroid FNA.", "critical": true}, {"id": "thyroid_bx_2", "label": "Real-time needle visualisation — tip confirmed within nodule throughout sampling", "detail": "Fanning technique (redirecting needle within nodule) increases cellular yield for FNA.", "critical": true}, {"id": "thyroid_bx_3", "label": "FNA: 25-27 gauge, 10-20 passes | Core biopsy: 18-20 gauge, 2-3 cores", "detail": "Core biopsy preferred for follicular neoplasm evaluation and molecular testing.", "critical": false}, {"id": "thyroid_bx_4", "label": "On-site cytology adequacy confirmed (if available) or minimum 6 passes per nodule", "detail": "Rapid on-site evaluation (ROSE) reduces non-diagnostic rate to less than 5%.", "critical": false}, {"id": "thyroid_bx_5", "label": "Post-procedure haematoma assessed — apply pressure for 5-10 minutes", "detail": "Haematoma is the most common complication; rarely requires intervention.", "critical": false}]', 4);

SELECT module, sectionName, sortOrder FROM navigatorOverrides WHERE module IN ('breast', 'thyroid') ORDER BY module, sortOrder;

